INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('23ddb957-c31f-4ec9-9fcc-e02bc5316c5c'::uuid, 'card_description', 'Two badly damaged Roman milestones turned up inside the walls of this villa. Its builders had reused them as stone for a house that probably had around 40 rooms in use.', 'A farmer digging out a ferret found Rockbourne Roman Villa in 1942. Two Roman milestones were reused in its fabric, and in 1967 a pottery jar yielded a hoard of 7717 bronze coins.', 'teaser-card-s049-rollback:23ddb957-c31f-4ec9-9fcc-e02bc5316c5c:card_description', 'rollback of teaser-card-s049: card_description ''A farmer digging out a ferret found Rockbourne Roman Villa in 1942. Two Roman milestones were reused in its fabric, and in 1967 a pottery jar yielded a hoard of 7717 bronze coins.'' restored on Rockbourne Roman Villa', 'e1b0b87c5ad5b6d1d330e7f916fbd20a7326d43265438d5ce201c6e1c70b28a2|1a4589568b3781f0d4fa5d77b11304b0c2cb5d65a2bdef5ef8267b107923f0c7|1a4589568b3781f0d4fa5d77b11304b0c2cb5d65a2bdef5ef8267b107923f0c7', '[{"source": "lane WB run wb-shorts-d81-a2-2026-11-12: writer card_writer:teaser-rewrite2-001", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "Two badly damaged Roman milestones turned up inside the walls of this villa. Its builders had reused them as stone for a house that probably had around 40 rooms in use."}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: checker card_fact_checker:teaser-check2-001 (check2), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "two Roman milestones were found at the site [S3]; the milestones are badly damaged [S3]; the site is a villa [S1]; the milestones were found built into the fabric of the villa [S3]; they had been re-used as building stone for the villa [S3]; the house probably had around 40 rooms in use [S2]"}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "Roman milestones turned up inside the walls of this villa. [SUPPORTED: https://romaninscriptionsofbritain.org/inscriptions/3518]; There were two such milestones. [SUPPORTED: https://romaninscriptionsofbritain.org/inscriptions/3518]; The milestones were badly damaged. [SUPPORTED: https://romaninscriptionsofbritain.org/inscriptions/3518]; The milestones are Roman milestones. [SUPPORTED: https://romaninscriptionsofbritain.org/inscriptions/3517]; The villa''s builders had reused the milestones as stone for a house. [SUPPORTED: https://romaninscriptionsofbritain.org/inscriptions/3517]; The house probably had around 40 rooms in use. [SUPPORTED: https://www.hampshireculture.org.uk/news/rockbourne-roman-villa-re-opens-season]"}]'::jsonb),
    ('255f657f-15e7-4eee-b9d9-7a30ce68d130'::uuid, 'card_description', 'Two aqueducts gave this Roman fort a copious water supply. One was fed from an impounded source to the west, and the fort was built on high ground with clear views around the site.', 'On high ground by Dere Street, the Roman fort of Longovicium drew water from two aqueducts, one fed by a stone-faced dam that harnessed 21 springs and stood 20 feet high.', 'teaser-card-s049-rollback:255f657f-15e7-4eee-b9d9-7a30ce68d130:card_description', 'rollback of teaser-card-s049: card_description ''On high ground by Dere Street, the Roman fort of Longovicium drew water from two aqueducts, one fed by a stone-faced dam that harnessed 21 springs and stood 20 feet high.'' restored on Longovicium', '9ef1643d86dea81a8ed61f0315f33884e300ef50c084425f428dac6d24162e3c|038ce0ff74342ee020aa74df8f45429ca0a119fd346c553938c67f974e3f7216|038ce0ff74342ee020aa74df8f45429ca0a119fd346c553938c67f974e3f7216', '[{"source": "lane WB run wb-shorts-d81-a2-2026-11-12: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "Two aqueducts gave this Roman fort a copious water supply. One was fed from an impounded source to the west, and the fort was built on high ground with clear views around the site."}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "the site had two aqueducts [S5]; they gave it a copious water supply [S5]; it is a Roman fort [S1]; one aqueduct was fed from an impounded source [S5]; that source lay to the west [S5]; the fort was built on high ground [S4]; it had clear views around the site [S4]"}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "Two aqueducts gave this fort its water supply. [SUPPORTED: https://www.roman-britain.co.uk/places/lanchester-roman-aqueduct/]; The fort is a Roman fort. [SUPPORTED: https://www.durham.gov.uk/media/10172/Lanchester-Conservation-Area-Character-Appraisal/pdf/LanchesterConservationAreaAppraisal.pdf?m=636736391333070000]; The fort''s water supply was copious. [SUPPORTED: https://www.roman-britain.co.uk/places/lanchester-roman-aqueduct/]; One of the aqueducts was fed from an impounded source. [SUPPORTED: https://www.roman-britain.co.uk/places/lanchester-roman-aqueduct/]; The impounded source lay to the west of the fort. [SUPPORTED: https://www.durham.gov.uk/media/10172/Lanchester-Conservation-Area-Character-Appraisal/pdf/LanchesterConservationAreaAppraisal.pdf?m=636736391333070000]; The fort was built on high ground. [SUPPORTED: https://www.durham.gov.uk/media/10172/Lanchester-Conservation-Area-Character-Appraisal/pdf/LanchesterConservationAreaAppraisal.pdf?m=636736391333070000]; The fort had clear views around the site. [SUPPORTED: https://www.durham.gov.uk/media/10172/Lanchester-Conservation-Area-Character-Appraisal/pdf/LanchesterConservationAreaAppraisal.pdf?m=636736391333070000]"}]'::jsonb),
    ('2753c6bb-1b90-4d49-8e59-b037bf1df930'::uuid, 'card_description', 'Neanderthals often lived in this rock shelter on the bank of a small ravine. Flint tools found here show extensive Neanderthal traffic, and some flint came from over 100 kilometers away.', 'Neanderthals lived in Abrigo de la Quebrada, a rock shelter on a small ravine, only from June to October, and some of the flint they knapped there came from over 100 kilometers away.', 'teaser-card-s049-rollback:2753c6bb-1b90-4d49-8e59-b037bf1df930:card_description', 'rollback of teaser-card-s049: card_description ''Neanderthals lived in Abrigo de la Quebrada, a rock shelter on a small ravine, only from June to October, and some of the flint they knapped there came from over 100 kilometers away.'' restored on Abrigo de la Quebrada', 'dc73d45b57ddab219ea83c34a3e46e56ad0019fc31bf2b3895edd5d899f09290|6b4494ee6a3b55ce5b862883d1b14fd4987fc7dfd499855581b3839ba5be7db8|6b4494ee6a3b55ce5b862883d1b14fd4987fc7dfd499855581b3839ba5be7db8', '[{"source": "lane WB run wb-shorts-d81-a2-2026-11-12: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "Neanderthals often lived in this rock shelter on the bank of a small ravine. Flint tools found here show extensive Neanderthal traffic, and some flint came from over 100 kilometers away."}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "Neanderthals frequently occupied the site [S2]; it is a rock shelter [S3]; it lies on the bank of a small ravine [S3]; flint tools were found here [S4]; they show extensive Neanderthal traffic [S4]; some of the flint came from over 100 kilometres away [S5]"}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "Neanderthals often lived in this rock shelter. [SUPPORTED: https://repositorio.ulisboa.pt/server/api/core/bitstreams/5db83dbf-a5af-4808-b21c-84a7cdd378be/content]; The site is a rock shelter. [SUPPORTED: https://repositorio.ulisboa.pt/server/api/core/bitstreams/5db83dbf-a5af-4808-b21c-84a7cdd378be/content]; The rock shelter is on the bank of a ravine. [SUPPORTED: https://repositorio.ulisboa.pt/server/api/core/bitstreams/5db83dbf-a5af-4808-b21c-84a7cdd378be/content]; The ravine is small. [SUPPORTED: https://repositorio.ulisboa.pt/server/api/core/bitstreams/5db83dbf-a5af-4808-b21c-84a7cdd378be/content]; Flint tools were found here. [SUPPORTED: https://repositorio.ulisboa.pt/server/api/core/bitstreams/5db83dbf-a5af-4808-b21c-84a7cdd378be/content]; The flint tools show extensive Neanderthal traffic. [SUPPORTED: https://journals.ed.ac.uk/lithicstudies/article/view/783]; Some of the flint came from over 100 kilometers away. [SUPPORTED: https://repositorio.ulisboa.pt/server/api/core/bitstreams/5db83dbf-a5af-4808-b21c-84a7cdd378be/content]"}]'::jsonb),
    ('2c05946f-80d4-4caf-8294-f1e2948d69b9'::uuid, 'card_description', 'Cicero spoke highly of this city and appears to have been its patron. Before that, the city struck its own coins and sided with Carthage after the battle of Cannae, allied with Capua.', 'Atella, an Oscan city north of Naples, sided with Carthage after Cannae. Rome occupied it in 210 BC and executed its chief citizens, yet ruins of walls, houses and tombs remain.', 'teaser-card-s049-rollback:2c05946f-80d4-4caf-8294-f1e2948d69b9:card_description', 'rollback of teaser-card-s049: card_description ''Atella, an Oscan city north of Naples, sided with Carthage after Cannae. Rome occupied it in 210 BC and executed its chief citizens, yet ruins of walls, houses and tombs remain.'' restored on Atella', '03339a6496fb15babe4f7101ea9c259c327d43a88d6d1296ed3f8b6004ec973e|4fbf6f6dce3fdf322f25b46a6acc269660dfe0d99f75bfdba05b8ec032909d4a|4fbf6f6dce3fdf322f25b46a6acc269660dfe0d99f75bfdba05b8ec032909d4a', '[{"source": "lane WB run wb-shorts-d81-a2-2026-11-12: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "Cicero spoke highly of this city and appears to have been its patron. Before that, the city struck its own coins and sided with Carthage after the battle of Cannae, allied with Capua."}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "Cicero spoke highly of the city [S2]; Cicero appears to have been its patron [S2]; it was a city [S1]; the events of the second sentence came before Cicero''s time [S1, S2]; the city struck its own coins [S1]; it sided with Carthage after the battle of Cannae [S1]; it was allied with Capua [S1]"}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "Cicero spoke highly of this city. [SUPPORTED: https://www.thelatinlibrary.com/cicero/fam13.shtml]; Cicero appears to have been the city''s patron. [SUPPORTED: https://www.thelatinlibrary.com/cicero/fam13.shtml]; The city struck its own coins. [SUPPORTED: http://snible.org/coins/hn/campania.html]; The coinage and the siding with Carthage came before Cicero''s time. [SUPPORTED: http://snible.org/coins/hn/campania.html]; The city sided with Carthage. [SUPPORTED: https://en.wikisource.org/wiki/From_the_Founding_of_the_City/Book_22]; The city sided with Carthage after the battle of Cannae. [SUPPORTED: https://en.wikisource.org/wiki/From_the_Founding_of_the_City/Book_22]; The city was allied with Capua when it sided with Carthage. [SUPPORTED: http://snible.org/coins/hn/campania.html]"}]'::jsonb),
    ('34139009-7bb5-42d7-b9d1-f5163fdb856d'::uuid, 'card_description', 'About 3 miles of Iron Age ditch and bank run from northeast to southwest. Sauer and Lambrick suggest the ditch may have marked a tribal border, with two earthworks called Grim''s Ditch.', 'Once thought a Roman road, Aves Ditch is an Iron Age boundary running about 3 miles through Oxfordshire that may have divided the Dobunni from the Catuvellauni. A skull lay in its ditch.', 'teaser-card-s049-rollback:34139009-7bb5-42d7-b9d1-f5163fdb856d:card_description', 'rollback of teaser-card-s049: card_description ''Once thought a Roman road, Aves Ditch is an Iron Age boundary running about 3 miles through Oxfordshire that may have divided the Dobunni from the Catuvellauni. A skull lay in its ditch.'' restored on Aves Ditch', 'dcb2d3e83b97172c95382a9d101e50b59eae8d502f9a8b9035e6c749cd99f9ce|4f30548ea820cede40883e17e6158ff117142772b9e1acb94c1a8092606492bf|4f30548ea820cede40883e17e6158ff117142772b9e1acb94c1a8092606492bf', '[{"source": "lane WB run wb-shorts-d81-a2-2026-11-12: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "About 3 miles of Iron Age ditch and bank run from northeast to southwest. Sauer and Lambrick suggest the ditch may have marked a tribal border, with two earthworks called Grim''s Ditch."}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "the structure is about 3 miles long [S1]; it is an Iron Age structure [S1]; it is a ditch and bank [S1]; it runs on a northeast to southwest alignment [S1]; Sauer and Lambrick have suggested a function for it [S2]; the ditch may have marked a boundary between tribes [S2]; it may have done so together with two earthworks called Grim''s Ditch [S2]"}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "The site is an Iron Age ditch and bank [SUPPORTED: https://www.oxoniensia.org/volumes/2010/Hart2.pdf]; The ditch and bank run for about 3 miles [SUPPORTED: https://intarch.ac.uk/journal/issue56/13/full-text.html]; The ditch and bank run from northeast to southwest [SUPPORTED: https://intarch.ac.uk/journal/issue56/13/full-text.html]; Sauer suggests the ditch may have marked a tribal border [SUPPORTED: https://intarch.ac.uk/journal/issue56/13/full-text.html]; Lambrick suggests the ditch may have marked a tribal border [SUPPORTED: https://intarch.ac.uk/journal/issue56/13/full-text.html]; In Sauer''s suggestion the tribal border was marked together with earthworks called Grim''s Ditch [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA130528]; In Lambrick''s suggestion the tribal border was marked together with Grim''s Ditch [SUPPORTED: https://intarch.ac.uk/journal/issue56/13/full-text.html]; There are two earthworks called Grim''s Ditch associated with this tribal border [SUPPORTED: https://www.oxoniensia.org/volumes/2010/Hart2.pdf]"}]'::jsonb),
    ('4bde4866-94ec-41c2-a7c5-d38e3a2280ea'::uuid, 'card_description', 'A man''s upper arm bone from these caves has been tied to the Aurignacian culture. The bone is 35,000 years old, and the caves lie in a limestone cliff above a river.', 'In a limestone cliff above the river Samson, the Goyet Caves yielded 99 Neanderthal bones from at least five individuals, and their condition strongly suggests cannibalism.', 'teaser-card-s049-rollback:4bde4866-94ec-41c2-a7c5-d38e3a2280ea:card_description', 'rollback of teaser-card-s049: card_description ''In a limestone cliff above the river Samson, the Goyet Caves yielded 99 Neanderthal bones from at least five individuals, and their condition strongly suggests cannibalism.'' restored on Goyet Caves', 'efca336e6477a86fb3a43ae726f491d59e7a9e7d17edbdb8db0c23d9e5968ec8|3cc53798e49ed5239e337b2c3c8c1c12cd2316d5f4287c95e727498fdc1952ee|3cc53798e49ed5239e337b2c3c8c1c12cd2316d5f4287c95e727498fdc1952ee', '[{"source": "lane WB run wb-shorts-d81-a2-2026-11-12: writer card_writer:teaser-write-002", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "A man''s upper arm bone from these caves has been tied to the Aurignacian culture. The bone is 35,000 years old, and the caves lie in a limestone cliff above a river."}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: checker card_fact_checker:teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "a man''s upper arm bone (humerus) comes from these caves [S3]; the bone has been associated with the Aurignacian culture [S3]; the bone is 35,000 years old [S3]; the site is a set of caves [S1]; the caves lie in a limestone cliff [S1]; the cliff is above a river [S1]"}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "An upper arm bone (humerus) from these caves has been tied to the Aurignacian culture. [SUPPORTED: https://reich.hms.harvard.edu/sites/reich.hms.harvard.edu/files/inline-files/FuQ_nature17993-s1.pdf]; The upper arm bone is a man''s. [SUPPORTED: https://reich.hms.harvard.edu/sites/reich.hms.harvard.edu/files/inline-files/FuQ_nature17993-s1.pdf]; The bone is 35,000 years old. [SUPPORTED: https://reich.hms.harvard.edu/sites/reich.hms.harvard.edu/files/inline-files/FuQ_nature17993-s1.pdf]; The caves lie in a cliff. [SUPPORTED: https://www.patrimoineculturel.org/documents/fichier/1/2/20200514_081704balade_goyet_web.pdf]; The cliff is limestone. [SUPPORTED: https://www.patrimoineculturel.org/documents/fichier/1/2/20200514_081704balade_goyet_web.pdf]; The caves lie above a river. [SUPPORTED: https://www.patrimoineculturel.org/documents/fichier/1/2/20200514_081704balade_goyet_web.pdf]"}]'::jsonb),
    ('a627df4e-f241-478e-b8ab-273e67f52441'::uuid, 'card_description', 'A ceremonial axe head of jadeitite lay in the peat bogs along this causeway. The ancient causeway was discovered in 1970 during peat digging, and it is named after the man who found it.', 'Oak planks laid end-to-end on crossed pegs of ash, oak and lime: the Sweet Track, built in 3807 or 3806 BC across a Somerset marsh, was used for only around ten years, then abandoned.', 'teaser-card-s049-rollback:a627df4e-f241-478e-b8ab-273e67f52441:card_description', 'rollback of teaser-card-s049: card_description ''Oak planks laid end-to-end on crossed pegs of ash, oak and lime: the Sweet Track, built in 3807 or 3806 BC across a Somerset marsh, was used for only around ten years, then abandoned.'' restored on Sweet Track', '997129a017f19e3999804df5638e4e21de344f687f3f09acc92df2cbdb21347e|e6795c9760892448cb0d4bc75e5962822c901ed592cac858555624cb751ea5d2|e6795c9760892448cb0d4bc75e5962822c901ed592cac858555624cb751ea5d2', '[{"source": "lane WB run wb-shorts-d81-a2-2026-11-12: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "A ceremonial axe head of jadeitite lay in the peat bogs along this causeway. The ancient causeway was discovered in 1970 during peat digging, and it is named after the man who found it."}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "a ceremonial axe head was found along the site [S3]; the axe head is made of jadeitite [S3]; it lay in the peat bogs along the site''s length [S3]; the site is an ancient causeway [S1]; it was discovered in 1970 [S4]; it was discovered during peat digging [S4]; it is named after the man who found it [S1, S4]"}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "An axe head lay in the peat bogs along this causeway (the Sweet Track). [SUPPORTED: https://swheritage.org.uk/news/stonehenge/]; The axe head is of jadeitite. [SUPPORTED: https://swheritage.org.uk/news/stonehenge/]; The axe head is ceremonial. [SUPPORTED: https://swheritage.org.uk/news/stonehenge/]; The causeway is ancient. [SUPPORTED: https://archaeologyathull.wordpress.com/archaeology-of-britain/s/sweet-track/]; The causeway was discovered in 1970. [SUPPORTED: https://archaeologyathull.wordpress.com/archaeology-of-britain/s/sweet-track/]; It was discovered during peat digging. [SUPPORTED: https://archaeologyathull.wordpress.com/archaeology-of-britain/s/sweet-track/]; It is named after the man who found it. [SUPPORTED: https://archaeologyathull.wordpress.com/archaeology-of-britain/s/sweet-track/]"}]'::jsonb),
    ('b740c74a-83ce-4e01-a07c-87ab90574750'::uuid, 'card_description', 'Three Maya stelae and an altar form the heart of this small site. Early work around it and Cancuen, 20 kilometres south, found signs of people from Late Preclassic to Late Classic times.', 'On an east-facing scarp, the three stelae and altar of Tres Islas mimic the E-Group at Uaxactun, a perfect place to watch the sunrise at this Early Classic Maya capital.', 'teaser-card-s049-rollback:b740c74a-83ce-4e01-a07c-87ab90574750:card_description', 'rollback of teaser-card-s049: card_description ''On an east-facing scarp, the three stelae and altar of Tres Islas mimic the E-Group at Uaxactun, a perfect place to watch the sunrise at this Early Classic Maya capital.'' restored on Tres Islas', 'eb33127aafd3c716b5202dd219c273b52b09d119aa849b3618ceb26444d4817d|06a2962e98cd02f481c05a19480fc6e7b65a64aa282055ae040b3758d7840c20|06a2962e98cd02f481c05a19480fc6e7b65a64aa282055ae040b3758d7840c20', '[{"source": "lane WB run wb-shorts-d81-a2-2026-11-12: writer card_writer:teaser-rewrite2-001", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "Three Maya stelae and an altar form the heart of this small site. Early work around it and Cancuen, 20 kilometres south, found signs of people from Late Preclassic to Late Classic times."}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: checker card_fact_checker:teaser-check2-002 (check2), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "the site''s main feature is three Maya stelae [S2]; an altar is part of that main feature [S2]; the site is small [S1]; the investigations around the site and Cancuen were early (preliminary) work [S3]; Cancuen lies 20 kilometres south of the site (the site is 20 km north of Cancuen) [S1]; that work found evidence of people living in the area [S3]; the evidence spans the Late Preclassic to the Late Classic [S3]"}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "Three stelae form the heart of this site (Tres Islas). [SUPPORTED: https://www.mesoweb.com/Simposio/pdf/18/Tomasic_et_al.2005.pdf]; The stelae are Maya stelae. [SUPPORTED: https://www.mesoweb.com/Simposio/pdf/18/Tomasic_et_al.2005.pdf]; An altar, together with the three stelae, forms the heart of the site. [SUPPORTED: https://www.mesoweb.com/Simposio/pdf/17/Tomasic_y_Fahsen.2004.pdf]; The site is small. [SUPPORTED: https://www.mesoweb.com/Simposio/pdf/18/Tomasic_et_al.2005.pdf]; Early work was done around the site and Cancuen. [SUPPORTED: https://www.mesoweb.com/Simposio/pdf/17/Tomasic_y_Fahsen.2004.pdf]; Cancuen lies 20 kilometres south of the site. [SUPPORTED: https://www.mesoweb.com/Simposio/pdf/18/Tomasic_et_al.2005.pdf]; The early work around the site and Cancuen found signs of people from Late Preclassic times. [SUPPORTED: https://www.mesoweb.com/Simposio/pdf/17/Tomasic_y_Fahsen.2004.pdf]; The signs of people run to Late Classic times. [SUPPORTED: https://www.mesoweb.com/Simposio/pdf/17/Tomasic_y_Fahsen.2004.pdf]"}]'::jsonb),
    ('c097eec0-60d9-4c1c-84f7-16e869dd5ccd'::uuid, 'card_description', 'Two large portal stones stand outside the ring of this stone circle. The builders set the pair on the south-east side, where the stones frame a well defined entrance into the ring.', 'Beside Swinside Fell in southern Cumbria, the stone circle of Swinside, also called Sunkenkirk, opens to the south-east between two large portal stones set outside its ring of slate.', 'teaser-card-s049-rollback:c097eec0-60d9-4c1c-84f7-16e869dd5ccd:card_description', 'rollback of teaser-card-s049: card_description ''Beside Swinside Fell in southern Cumbria, the stone circle of Swinside, also called Sunkenkirk, opens to the south-east between two large portal stones set outside its ring of slate.'' restored on Swinside', 'c72dce07949f2810de04ca70f21dabf190769e8c1bd293a1e9c379bc93f3d23d|513b837125f0c9dbe8e1818617e9f62338af785461f64708f44723c9c9a83957|513b837125f0c9dbe8e1818617e9f62338af785461f64708f44723c9c9a83957', '[{"source": "lane WB run wb-shorts-d81-a2-2026-11-12: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "Two large portal stones stand outside the ring of this stone circle. The builders set the pair on the south-east side, where the stones frame a well defined entrance into the ring."}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: checker card_fact_checker:teaser-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "the site is a stone circle [S1]; there are two portal stones [S2]; the portal stones are large [S2]; the portal stones stand outside the circumference of the circle [S2]; the builders placed the pair [S2]; the pair is on the south-east side [S2]; the stones define a well defined entrance into the circle [S2]"}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "This stone circle has two portal stones standing outside its ring [SUPPORTED: https://www.stonepages.com/england/swinside.html]; The site is a stone circle [SUPPORTED: https://www.stonepages.com/england/swinside.html]; There are two portal stones [SUPPORTED: https://www.britainexpress.com/counties/cumbria/ancient/swinside.htm]; The two portal stones are large [SUPPORTED: http://www.stone-circles.org.uk/stone/sunkenkirk.htm]; The portal stones stand outside the ring [SUPPORTED: https://www.isleofalbion.co.uk/sites/45/swinside.php]; The pair stands on the south-east side [SUPPORTED: https://www.britainexpress.com/counties/cumbria/ancient/swinside.htm]; The builders set the pair there (the south-east entrance is original) [SUPPORTED: https://www.isleofalbion.co.uk/sites/45/swinside.php]; The portal stones frame an entrance into the ring [SUPPORTED: http://www.stone-circles.org.uk/stone/sunkenkirk.htm]; The entrance is well defined [SUPPORTED: https://www.stonepages.com/england/swinside.html]"}]'::jsonb),
    ('c7d33a59-e6ed-46e1-ad3f-5598b699727b'::uuid, 'card_description', 'Compared to a giant wedding cake, the earthworks of an Iron Age fort top a hill. The ditch and outer bank around the whole fort take in three hills, two of them little more than spurs.', 'Atop Herefordshire Beacon in the Malvern Hills, British Camp''s earthworks have been compared to a giant wedding cake: an Iron Age hill fort thought first built in the 2nd century BC.', 'teaser-card-s049-rollback:c7d33a59-e6ed-46e1-ad3f-5598b699727b:card_description', 'rollback of teaser-card-s049: card_description "Atop Herefordshire Beacon in the Malvern Hills, British Camp''s earthworks have been compared to a giant wedding cake: an Iron Age hill fort thought first built in the 2nd century BC." restored on British Camp', '80fdf3d89e02031f2fce8120277f9f05c8c44b5ba0e08a66a6b5cbfe0d56c0ba|ee8a340f7909c22c3bc0b476386ef8774223e8ef8166dbd853c996a23a93dea2|ee8a340f7909c22c3bc0b476386ef8774223e8ef8166dbd853c996a23a93dea2', '[{"source": "lane WB run wb-shorts-d81-a2-2026-11-12: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "Compared to a giant wedding cake, the earthworks of an Iron Age fort top a hill. The ditch and outer bank around the whole fort take in three hills, two of them little more than spurs."}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: checker card_fact_checker:teaser-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "the site''s earthworks have been compared to a giant wedding cake [S2]; it is an Iron Age fort [S1]; the fort tops a hill [S1]; a ditch and an outer (counterscarp) bank run around the whole fort [S3]; the ditch and bank take in three hills [S3]; two of those hills are little more than spurs [S3]"}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "The earthworks (of British Camp) have been compared to a giant wedding cake. [SUPPORTED: https://www.historyhit.com/guides/best-historic-sites-in-herefordshire/]; The earthworks are those of a fort. [SUPPORTED: https://htt.herefordshire.gov.uk/her-search/monuments-search/search/Monument?ID=932]; The fort is of the Iron Age. [SUPPORTED: https://htt.herefordshire.gov.uk/her-search/monuments-search/search/Monument?ID=932]; The earthworks top a hill. [SUPPORTED: https://htt.herefordshire.gov.uk/her-search/monuments-search/search/Monument?ID=932]; A ditch and an outer bank run around the whole fort. [SUPPORTED: https://htt.herefordshire.gov.uk/her-search/monuments-search/search/Monument?ID=932]; The ditch and outer bank take in three hills. [SUPPORTED: https://htt.herefordshire.gov.uk/her-search/monuments-search/search/Monument?ID=932]; Two of the three hills are little more than spurs. [SUPPORTED: https://htt.herefordshire.gov.uk/her-search/monuments-search/search/Monument?ID=932]"}]'::jsonb),
    ('d24b6616-bd08-4edc-b385-cd5200383e9b'::uuid, 'card_description', 'The last word of this road''s name comes from the Scandinavian word for road. A record of 1627 ties the name to John Talbot, credited with improving the road''s summit section.', 'Between the forts of Glossop and Brough-on-Noe ran Doctor''s Gate, a Roman road named for Dr John Talbot, credited with improving its summit in the late 15th century.', 'teaser-card-s049-rollback:d24b6616-bd08-4edc-b385-cd5200383e9b:card_description', 'rollback of teaser-card-s049: card_description "Between the forts of Glossop and Brough-on-Noe ran Doctor''s Gate, a Roman road named for Dr John Talbot, credited with improving its summit in the late 15th century." restored on Doctor''s Gate', '7d13f15fd70697c0d2e42c50165092012a4a840137b86a8d0c7975dd0ac710f1|596c7f416afbf6a28340de17043acb5ec50f29a1e355215ac3bded749eb90632|596c7f416afbf6a28340de17043acb5ec50f29a1e355215ac3bded749eb90632', '[{"source": "lane WB run wb-shorts-d81-a2-2026-11-12: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "The last word of this road''s name comes from the Scandinavian word for road. A record of 1627 ties the name to John Talbot, credited with improving the road''s summit section."}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "the site is a road (route) [S1, S2]; the last word of its name comes from the Scandinavian word for road [S1]; the name was recorded in 1627 [S1]; the name is tied to John Talbot [S1]; John Talbot is credited (attributed) with improving the road''s summit section [S1]"}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "The last word of this road''s name (Doctor''s Gate) comes from the Scandinavian word for road. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA112649]; The site is a road. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA112649]; A record of 1627 exists of the road''s name. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA112649]; The 1627 record ties the name to John Talbot. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA112649]; John Talbot is credited with improving the road''s summit section. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA112649]"}]'::jsonb),
    ('d569aff2-99e0-4964-b6a5-a197bea12cda'::uuid, 'card_description', 'Too small to be a hillfort, these earthworks also hold no defensible position. Digs here recovered finds such as a small flint blade, animal bones and charcoal, dated to the Iron Age.', 'In Hatfield Forest, a zig-zag causeway formed by 2 almost parallel ditches links the mound of Portingbury Hills to an enclosure. Digs in 1964–1965 found a small flint blade 4 cm long.', 'teaser-card-s049-rollback:d569aff2-99e0-4964-b6a5-a197bea12cda:card_description', 'rollback of teaser-card-s049: card_description ''In Hatfield Forest, a zig-zag causeway formed by 2 almost parallel ditches links the mound of Portingbury Hills to an enclosure. Digs in 1964–1965 found a small flint blade 4 cm long.'' restored on Portingbury Hills', 'b75040bb2bf33b3dff81b53888017b141680ccc02929794950818ef8d2deeea1|c645ecc956609c813e7be9833557d879508a1163cde987cb1c989124e59855ff|c645ecc956609c813e7be9833557d879508a1163cde987cb1c989124e59855ff', '[{"source": "lane WB run wb-shorts-d81-a2-2026-11-12: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "Too small to be a hillfort, these earthworks also hold no defensible position. Digs here recovered finds such as a small flint blade, animal bones and charcoal, dated to the Iron Age."}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "the site consists of earthworks [S2]; the earthworks are too small to be a hillfort [S2]; they are not in a defensible position [S2]; excavations were carried out here [S1]; the finds include a small flint blade [S1]; the finds include animal bones [S1]; the finds include charcoal [S1]; the finds are dated to the Iron Age [S1]"}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "These earthworks (Portingbury Hills) are too small to be a hillfort. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA108506]; The earthworks hold no defensible position. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA108506]; The site is a group of earthworks. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA108506]; Digs were carried out here. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA108506]; The digs recovered a small flint blade. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA108506]; The digs recovered animal bones. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA108506]; The digs recovered charcoal. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA108506]; The finds are dated to the Iron Age. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA108506]"}]'::jsonb),
    ('f4e3fdef-07f1-4327-b0db-c01c671bfafc'::uuid, 'card_description', 'One end of a large cairn holds a Neolithic tomb, the other a stone box grave. The tomb is a tripod portal tomb, set at the foot of a mountain''s western flank, above a stream.', 'At the foot of Slieve Gullion, the granite capstone of Ballykeel Dolmen balances on the tips of three portal stones. Its chamber held three highly decorated Ballyalton bowls.', 'teaser-card-s049-rollback:f4e3fdef-07f1-4327-b0db-c01c671bfafc:card_description', 'rollback of teaser-card-s049: card_description ''At the foot of Slieve Gullion, the granite capstone of Ballykeel Dolmen balances on the tips of three portal stones. Its chamber held three highly decorated Ballyalton bowls.'' restored on Ballykeel Dolmen', '80909be22dbfd4302dc04fd8947c12caa21baaf3a34d81cc5c26f37252699252|39c32bc21047e25a5cadb50b99d89d0920e494221c501c6449930c155612b7c3|39c32bc21047e25a5cadb50b99d89d0920e494221c501c6449930c155612b7c3', '[{"source": "lane WB run wb-shorts-d81-a2-2026-11-12: writer card_writer:teaser-write-004", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "One end of a large cairn holds a Neolithic tomb, the other a stone box grave. The tomb is a tripod portal tomb, set at the foot of a mountain''s western flank, above a stream."}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: checker card_fact_checker:teaser-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "the site has a large cairn [S3]; one end of the cairn holds a tomb [S3]; the tomb is Neolithic [S1]; the other end of the cairn holds a stone box grave (a cist) [S3]; the tomb is a tripod portal tomb [S1]; the tomb is set at the foot of the western flank of a height [S1]; the tomb lies above a stream [S2]"}, {"source": "lane WB run wb-shorts-d81-a2-2026-11-12: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-d81-a2-2026-11-12/OUTCOMES.jsonl", "quote": "One end of a large cairn holds a tomb (Ballykeel Dolmen). [SUPPORTED: https://cdn.ringofgullion.org/2015/01/SATIuncoveringthepast.pdf]; The cairn is large. [SUPPORTED: https://monumentalireland.ie/monument-details/?monument_id=937]; The tomb is Neolithic. [SUPPORTED: https://monumentalireland.ie/monument-details/?monument_id=937]; The other end of the cairn holds a stone box grave. [SUPPORTED: https://cdn.ringofgullion.org/2015/01/SATIuncoveringthepast.pdf]; The tomb is a tripod portal tomb. [SUPPORTED: https://curiousireland.ie/ballykeel-dolmen/]; The tomb is set at the foot of a mountain''s western flank. [SUPPORTED: https://monumentalireland.ie/the-hags-chair/]; The tomb is set above a stream. [SUPPORTED: https://cdn.ringofgullion.org/2015/01/SATIuncoveringthepast.pdf]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 13;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s049-rollback', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s049-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s049-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 13 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s049-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s049-rollback' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
